/**
 * Cache file IO for per-provider model lists.
 *
 * One file per provider key under <cacheDir>/<providerKey>.json. TTL is
 * 7 days. Callers decide whether to honor staleness — readCache just
 * reads, isStale just checks. Malformed/missing files yield undefined.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { userHome } from "../settings/manager.js";

export interface CachedModel {
  id: string;
  contextLength: number;
  maxOutputTokens: number;
}

export interface ModelCacheFile {
  fetchedAt: string;
  providerKey: string;
  models: CachedModel[];
}

const TTL_MS = 7 * 24 * 3600 * 1000;

export function readCache(cacheDir: string, providerKey: string): ModelCacheFile | undefined {
  const path = join(cacheDir, `${providerKey}.json`);
  if (!existsSync(path)) return undefined;
  try {
    const raw = readFileSync(path, "utf-8");
    const parsed = JSON.parse(raw) as ModelCacheFile;
    if (!parsed || !Array.isArray(parsed.models)) return undefined;
    return parsed;
  } catch {
    return undefined;
  }
}

export function writeCache(
  cacheDir: string,
  providerKey: string,
  models: CachedModel[],
): ModelCacheFile {
  if (!existsSync(cacheDir)) mkdirSync(cacheDir, { recursive: true });
  const payload: ModelCacheFile = {
    fetchedAt: new Date().toISOString(),
    providerKey,
    models,
  };
  writeFileSync(join(cacheDir, `${providerKey}.json`), JSON.stringify(payload, null, 2), "utf-8");
  return payload;
}

export function isStale(file: ModelCacheFile, now: number = Date.now()): boolean {
  const ts = Date.parse(file.fetchedAt);
  if (!Number.isFinite(ts)) return true;
  return now - ts > TTL_MS;
}

export function defaultCacheDir(): string {
  // userHome() (not raw homedir(), which bun caches at process start) so a
  // relocated/test HOME redirects the cache dir instead of writing real ~/.code-shell.
  return join(userHome(), ".code-shell", "cache", "models");
}

const OPENROUTER_SNAPSHOT = join(HERE, "..", "data", "openrouter-models.json");

interface RawOpenAIShape {
  data?: Array<{
    id: string;
    context_window?: number;
    max_completion_tokens?: number;
    context_length?: number;
  }>;
}
interface RawOllamaShape {
  models?: Array<{ name: string }>;
}
interface RawAnthropicShape {
  data?: Array<{ id: string; context_window?: number; max_output_tokens?: number }>;
}
interface RawGeminiShape {
  models?: Array<{ name: string; inputTokenLimit?: number; outputTokenLimit?: number }>;
}
interface OpenRouterSnapshotShape {
  models?: Array<{ id: string; contextLength?: number; maxOutputTokens?: number }>;
}

export async function fetchModelList(
  provider: FetcherProvider,
  opts: FetchOptions,
): Promise<FetchResult> {
  const meta = getKindMeta(provider.kind);

  if (!opts.refresh) {
    const cached = readCache(opts.cacheDir, provider.key);
    if (cached && !isStale(cached)) return { ...cached, fromCache: true };
  }

  const filtered = raw.filter((m) => meta.chatFilter(m.id));
  const sorted = sortByRecency(filtered);
  const enriched = enrichFromStaticCatalog(provider.kind, sorted);
  const finalModels = enrichFromOpenRouterSnapshot(provider.kind, enriched);
  const file = writeCache(opts.cacheDir, provider.key, finalModels);
  return file;
} catch (err) {
  const msg = (err as Error).message || String(err);
  return errorResult(provider.key, opts.cacheDir, msg, provider.kind);
}
